import { sql, type SQL } from 'drizzle-orm';
import {
  boolean,
  customType,
  integer,
  timestamp,
  uuid,
  type AnyPgColumn,
} from 'drizzle-orm/pg-core';

/**
 * Building blocks shared by the table definitions.
 *
 * Foreign keys are deliberately **not** declared here. Every foreign key must be
 * `deferrable` (data-model §2) so revert and clone can write rows in any order, and Drizzle
 * can't express that. They're written in SQL at the end of the migration instead; see
 * migrations/README.md.
 */

/** A UUIDv7 primary key, generated by Postgres 18 (`uuidv7()`), time-ordered. */
export const idColumn = () =>
  uuid()
    .primaryKey()
    .default(sql`uuidv7()`);

/** `created_at`, `updated_at` and `version` on universes, maps and entities (data-model §2). */
export const stamps = () => ({
  createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  version: integer().notNull().default(1),
});

export const isSpoilerColumn = () => boolean().notNull().default(false);

/** `column in ('a', 'b', …)`, for check constraints generated from a registry list. */
export function oneOf(column: AnyPgColumn, values: readonly string[]): SQL {
  return sql`${column} in (${sql.raw(values.map(literal).join(', '))})`;
}

/** `column ~ 'pattern'`, for format checks shared with the Zod schemas (@ge/domain patterns). */
export function matches(column: AnyPgColumn, pattern: string): SQL {
  return sql`${column} ~ ${sql.raw(literal(pattern))}`;
}

/** A SQL string literal. Only ever called with constants from @ge/domain, never user input. */
function literal(value: string): string {
  return `'${value.replaceAll("'", "''")}'`;
}

/**
 * A Postgres full-text search vector (M7-T6). Drizzle has no type for it; its text form is what
 * a select returns, though nothing reads it back: queries use it inside SQL.
 */
export const tsvector = customType<{ data: string }>({ dataType: () => 'tsvector' });

/**
 * Raw bytes (M8-T1: hashes and encrypted secrets). Drizzle 0.45 has no `bytea` column; node-pg
 * reads and writes it as a Buffer.
 */
export const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType: () => 'bytea',
});
